const closeMenu = () => {
  menuButton.setAttribute("aria-expanded", "false");
  menuButton.setAttribute("aria-label", translations[activeLocale].openMenu);
  mobileMenu.classList.remove("is-open");
  mobileMenu.setAttribute("aria-hidden", "true");
  mobileMenu.inert = true;
};

let successModalLastFocused = null;
let successModalInertState = [];

const closeSuccessModal = () => {
  if (successModal.hidden) return;
  successModal.hidden = true;
  document.body.classList.remove("modal-open");
  successModalInertState.forEach(({ element, inert }) => {
    element.inert = inert;
  });
  successModalInertState = [];
  if (successModalLastFocused instanceof HTMLElement) successModalLastFocused.focus();
  successModalLastFocused = null;
};

const openSuccessModal = () => {
  successModalLastFocused = document.activeElement;
  successModalInertState = [...document.body.children]
    .filter((element) => element !== successModal)
    .map((element) => ({ element, inert: element.inert }));
  successModalInertState.forEach(({ element }) => {
    element.inert = true;
  });
  successModal.hidden = false;
  document.body.classList.add("modal-open");
  successModalClose.focus();
};

successModalClose.addEventListener("click", closeSuccessModal);
successModal.addEventListener("click", closeSuccessModal);
successModalCard.addEventListener("click", (event) => event.stopPropagation());

window.addEventListener(
  "scroll",
  () => {
    header.classList.toggle("is-scrolled", window.scrollY > 18);
    backToTopButton.classList.toggle("is-visible", window.scrollY > 640);
    const scrollable = document.documentElement.scrollHeight - window.innerHeight;
    const progress = scrollable > 0 ? Math.min(window.scrollY / scrollable, 1) : 0;
    scrollProgress.style.transform = "scaleX(" + progress + ")";
  },
  { passive: true },
);

const prefersReducedMotion = () =>
  window.matchMedia("(prefers-reduced-motion: reduce)").matches ||
  document.documentElement.classList.contains("a11y-reduce-motion");

backToTopButton.addEventListener("click", () => {
  window.scrollTo({ top: 0, behavior: prefersReducedMotion() ? "auto" : "smooth" });
});

let shareToastTimer;
const showShareToast = (message) => {
  window.clearTimeout(shareToastTimer);
  shareToast.textContent = message;
  shareToast.classList.add("is-visible");
  shareToastTimer = window.setTimeout(() => {
    shareToast.classList.remove("is-visible");
  }, 2400);
};

const copyShareUrl = async () => {
  try {
    await navigator.clipboard.writeText(location.href);
  } catch {
    const input = document.createElement("textarea");
    input.value = location.href;
    input.setAttribute("readonly", "");
    input.style.position = "fixed";
    input.style.opacity = "0";
    document.body.append(input);
    input.select();
    document.execCommand("copy");
    input.remove();
  }
  showShareToast(companyData.linkCopied[activeLocale]);
};

shareButton.addEventListener("click", async () => {
  if (navigator.share) {
    try {
      await navigator.share({
        title: document.title,
        text: companyData.shareText[activeLocale],
        url: location.href,
      });
      return;
    } catch (error) {
      if (error?.name === "AbortError") return;
    }
  }
  await copyShareUrl();
});

menuButton.addEventListener("click", () => {
  const open = menuButton.getAttribute("aria-expanded") === "true";
  menuButton.setAttribute("aria-expanded", String(!open));
  menuButton.setAttribute(
    "aria-label",
    open ? translations[activeLocale].openMenu : translations[activeLocale].closeMenu,
  );
  mobileMenu.classList.toggle("is-open", !open);
  mobileMenu.setAttribute("aria-hidden", String(open));
  mobileMenu.inert = open;
});

document.querySelectorAll("[data-topic-index]").forEach((link) => {
  link.addEventListener("click", () => {
    const topicIndex = Number(link.dataset.topicIndex);
    const select = contactForm.querySelector('select[name="topic"]');
    if (Number.isInteger(topicIndex) && select.options[topicIndex]) {
      select.selectedIndex = topicIndex;
    }
  });
});

contactForm.addEventListener("submit", async (event) => {
  event.preventDefault();
  const company = companyContent[activeLocale] || companyContent.en;
  const data = new FormData(contactForm);
  const name = String(data.get("name") || "");
  const email = String(data.get("email") || "");
  const organization = String(data.get("organization") || "");
  const topic = String(data.get("topic") || company.topics[0]);
  const message = String(data.get("message") || "");
  const privacyAccepted = data.get("privacy") === "accepted";
  const honey = String(data.get("_honey") || "");
  const button = contactForm.querySelector('button[type="submit"]');
  const status = contactForm.querySelector(".form-status");

  button.disabled = true;
  button.textContent = company.formSending;
  status.className = "form-status";
  status.textContent = "";

  try {
    let response = null;
    let result = {};
    try {
      response = await fetch(contactFormEndpoint, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Accept: "application/json",
        },
        body: JSON.stringify({
          submissionId: crypto.randomUUID(),
          privacyAccepted,
          honey,
          name,
          email,
          organization,
          topic,
          message,
          locale: activeLocale,
          source: location.href,
        }),
      });
      result = await response.json().catch(() => ({}));
    } catch {
      response = null;
    }
    if (!response?.ok || String(result.success) !== "true") {
      const fallbackResponse = await fetch(contactFormFallbackEndpoint, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Accept: "application/json",
        },
        body: JSON.stringify({
          name,
          email,
          organization,
          topic,
          message,
          privacy: privacyAccepted ? "accepted" : "not accepted",
          language: activeLocale,
          source: location.href,
          _subject: "SpaPlus Global website enquiry",
          _captcha: "false",
          _template: "box",
          _cc: "palombo.r@gmail.com,s0509350015@gmail.com",
          _autoresponse:
            "Thank you for contacting SpaPlus Global. We have received your enquiry and our team will review it shortly.",
        }),
      });
      const fallbackResult = await fallbackResponse.json().catch(() => ({}));
      if (!fallbackResponse.ok || String(fallbackResult.success) !== "true") {
        throw new Error("Submission failed");
      }
    }
    contactForm.reset();
    renderTopics(company);
    status.textContent = "";
    openSuccessModal();
  } catch {
    status.classList.add("is-error");
    status.textContent = company.formError;
  } finally {
    button.disabled = false;
    button.textContent = company.formSubmit;
  }
});

languageSelect.addEventListener("change", (event) => {
  const locale = event.target.value;
  localStorage.setItem(localeStorageKey, locale);
  const root = location.hostname.endsWith("github.io") ? "/spaplus-global/" : "/";
  location.href = root + localePathMap[locale] + "/" + location.hash;
});
mobileMenu.querySelectorAll("a").forEach((link) => link.addEventListener("click", closeMenu));
const openLegalFromHash = () => {
  if (!location.hash) return;
  const target = document.getElementById(decodeURIComponent(location.hash.slice(1)));
  if (target && target.matches(".legal-section details")) target.open = true;
};
document.querySelectorAll('a[href="#privacy"], a[href="#accessibility"]').forEach((link) => {
  link.addEventListener("click", () => {
    const target = document.querySelector(link.getAttribute("href"));
    if (target) target.open = true;
  });
});
window.addEventListener("hashchange", openLegalFromHash);
document.addEventListener("keydown", (event) => {
  if (event.key === "Escape") {
    closeMenu();
    closeSuccessModal();
  }
  if (event.key === "Tab" && !successModal.hidden) {
    const focusable = [...successModalCard.querySelectorAll(
      'button:not([disabled]), a[href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])',
    )].filter((element) => !element.hidden && element.offsetParent !== null);
    if (!focusable.length) {
      event.preventDefault();
      successModalClose.focus();
      return;
    }
    const first = focusable[0];
    const last = focusable[focusable.length - 1];
    if (event.shiftKey && document.activeElement === first) {
      event.preventDefault();
      last.focus();
    } else if (!event.shiftKey && document.activeElement === last) {
      event.preventDefault();
      first.focus();
    }
  }
});

const revealElements = document.querySelectorAll("[data-reveal]");
if (prefersReducedMotion()) {
  revealElements.forEach((element) => element.classList.add("is-visible"));
} else {
  const observer = new IntersectionObserver(
    (entries) => entries.forEach((entry) => {
      if (entry.isIntersecting) {
        entry.target.classList.add("is-visible");
        observer.unobserve(entry.target);
      }
    }),
    { threshold: 0.14 },
  );
  revealElements.forEach((element) => observer.observe(element));
}

applyLocale(activeLocale);
openLegalFromHash();
